mapper.select:
SELECT r.* FROM qt_user_responses r
WHERE r.qt_content_id = #{qtContentId}
ORDER BY r.created_at ASC

mapper.update:
UPDATE qt_user_responses
SET meditation = #{meditation}, application = #{application}, prayer = #{prayer}, photos = #{photos}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT r.* FROM qt_user_responses r
WHERE r.user_id = #{userId}
ORDER BY r.created_at DESC
LIMIT #{size} OFFSET #{offset}
